Specification:
Three workers need three shared mutexes. Worker 1 uses A and B, worker 2 uses B and C, worker 3 uses C and A. Each worker holds its two mutexes at the same time, releases them, and returns. Main starts all three and waits. Every interleaving must terminate and all three workers must complete. On completion the program must print exactly one line `DONE done=1` and then exit; it must terminate.


Current program:
```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let mtx_a = Arc::new(Mutex::new(()));
    let mtx_b = Arc::new(Mutex::new(()));
    let mtx_c = Arc::new(Mutex::new(()));

    let (a1, b1) = (Arc::clone(&mtx_a), Arc::clone(&mtx_b));
    let w1 = thread::spawn(move || {
        let ga = a1.lock().unwrap();
        let gb = b1.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let (b2, c2) = (Arc::clone(&mtx_b), Arc::clone(&mtx_c));
    let w2 = thread::spawn(move || {
        let gb = b2.lock().unwrap();
        let gc = c2.lock().unwrap();
        drop(gc);
        drop(gb);
    });

    let (c3, a3) = (Arc::clone(&mtx_c), Arc::clone(&mtx_a));
    let w3 = thread::spawn(move || {
        let gc = c3.lock().unwrap();
        let ga = a3.lock().unwrap();
        drop(ga);
        drop(gc);
    });

    w1.join().unwrap();
    w2.join().unwrap();
    w3.join().unwrap();
}

```

